async function transitionOrder(id, next) {
  const order = await getOrder(id)
  if (order.status !== 'pending') throw new Error('invalid status')
  order.status = next
  await saveOrder(order)
  await sendNotice(order.owner, next)
}
// approveOrder / rejectOrder / cancelOrder 都改为调用 transitionOrder

